const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var jabalQidr = ee.Geometry.Point([40.833, 27.333]); // Jabal Qidr, Saudi Arabia
  var jabalBayda = ee.Geometry.Point([37.167, 27.667]); // Jabal Bayda, Saudi Arabia
  var bufferRadius = 1000; // 1km buffer around points
  var geomQidr = jabalQidr.buffer(bufferRadius);
  var geomBayda = jabalBayda.buffer(bufferRadius);

  var startDate = '2024-04-01';
  var endDate = '2024-04-30';

  // 2. Data Acquisition - Try Sentinel-2 first
  var s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(ee.Geometry.MultiPoint([jabalQidr, jabalBayda]));

  // Check if collection has data
  var colSize = s2Col.size().getInfo();
  if (colSize === 0) {
    // Try Landsat 9 as fallback
    var landsatCol = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterDate(startDate, endDate)
      .filterBounds(ee.Geometry.MultiPoint([jabalQidr, jabalBayda]));

    var landsatSize = landsatCol.size().getInfo();
    if (landsatSize === 0) {
      print("No Sentinel-2 or Landsat images found in April 2024.");
      print("<answer>C1</answer>");
      return;
    } else {
      // Use Landsat 9
      var image = landsatCol.median();
      // Landsat 9 surface reflectance bands (scaled by 0.0000275)
      var visBands = ['SR_B4', 'SR_B3', 'SR_B2']; // Red, Green, Blue
      var scaleFactor = 0.0000275;
      var offset = -0.2;

      // Calculate mean reflectance for each location
      var qidrVis = image.select(visBands)
        .multiply(scaleFactor).add(offset)
        .reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: geomQidr,
          scale: 1000,
          maxPixels: 1e9
        });
      var baydaVis = image.select(visBands)
        .multiply(scaleFactor).add(offset)
        .reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: geomBayda,
          scale: 1000,
          maxPixels: 1e9
        });

      // Get pixel counts
      var qidrCount = image.select(visBands[0])
        .reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geomQidr,
          scale: 1000,
          maxPixels: 1e9
        }).get(visBands[0]).getInfo();
      var baydaCount = image.select(visBands[0])
        .reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geomBayda,
          scale: 1000,
          maxPixels: 1e9
        }).get(visBands[0]).getInfo();

      print("Using Landsat 9 (Apr 2024 median)");
      print("Jabal Qidr pixels:", qidrCount, "Jabal Bayda pixels:", baydaCount);
    }
  } else {
    // Use Sentinel-2 with cloud masking
    // Add cloud probability from separate collection
    var cloudProbCol = ee.ImageCollection('COPERNICUS/S2_CLOUD_PROBABILITY')
      .filterDate(startDate, endDate)
      .filterBounds(ee.Geometry.MultiPoint([jabalQidr, jabalBayda]));

    // Join S2 with cloud probability
    var joinedCol = ee.Join.saveFirst('cloud_prob').apply({
      primary: s2Col,
      secondary: cloudProbCol,
      condition: ee.Filter.equals({
        leftField: 'system:index',
        rightField: 'system:index'
      })
    });

    // Function to mask clouds
    function maskClouds(img) {
      var cloudProb = ee.Image(img.get('cloud_prob')).select('probability');
      var mask = cloudProb.lt(20); // 20% cloud probability threshold
      return img.updateMask(mask).divide(10000); // Scale to 0-1
    }

    var maskedCol = ee.ImageCollection(joinedCol.map(maskClouds));
    var image = maskedCol.median();

    // Sentinel-2 visible bands (B2, B3, B4) = Blue, Green, Red
    var visBands = ['B2', 'B3', 'B4'];

    // Calculate mean reflectance for each location
    var qidrVis = image.select(visBands)
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geomQidr,
        scale: 1000,
        maxPixels: 1e9
      });
    var baydaVis = image.select(visBands)
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geomBayda,
        scale: 1000,
        maxPixels: 1e9
      });

    // Get pixel counts to check C2
    var qidrCount = image.select(visBands[0])
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geomQidr,
        scale: 1000,
        maxPixels: 1e9
      }).get(visBands[0]).getInfo();
    var baydaCount = image.select(visBands[0])
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geomBayda,
        scale: 1000,
        maxPixels: 1e9
      }).get(visBands[0]).getInfo();

    print("Using Sentinel-2 (Apr 2024 median)");
    print("Images found:", colSize);
    print("Jabal Qidr valid pixels:", qidrCount);
    print("Jabal Bayda valid pixels:", baydaCount);
  }

  // Check for C2: No valid pixels
  if (qidrCount === 0 || baydaCount === 0) {
    if (qidrCount === 0) print("No valid pixels at Jabal Qidr.");
    if (baydaCount === 0) print("No valid pixels at Jabal Bayda.");
    print("<answer>C2</answer>");
    return;
  }

  // Extract reflectance values
  var qidrValues = qidrVis.getInfo();
  var baydaValues = baydaVis.getInfo();

  // Calculate mean visible reflectance
  var qidrMean = (qidrValues[visBands[0]] + qidrValues[visBands[1]] + qidrValues[visBands[2]]) / 3;
  var baydaMean = (baydaValues[visBands[0]] + baydaValues[visBands[1]] + baydaValues[visBands[2]]) / 3;

  print("Jabal Qidr mean reflectance:", qidrMean.toFixed(4));
  print("Jabal Bayda mean reflectance:", baydaMean.toFixed(4));

  // Check for C3: Invalid values
  if (qidrMean === null || baydaMean === null || 
      isNaN(qidrMean) || isNaN(baydaMean) ||
      qidrMean < 0 || qidrMean > 1 || 
      baydaMean < 0 || baydaMean > 1) {
    print("Invalid reflectance values detected.");
    print("<answer>C3</answer>");
    return;
  }

  // Determine answer
  if (qidrMean < baydaMean) {
    print("Jabal Qidr is darker (lower reflectance).");
    print("<answer>A</answer>");
  } else {
    print("Jabal Qidr is not darker (equal or higher reflectance).");
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
